        LANGUAGE_WRAPPER = 'Let theta = {step_deg} degrees and b = {base_offset}. For k = 1, 2, ..., {n_terms}, define the angles A_k = (b + k)·theta and B_k = (b + k + {shift})·theta. Define the quantity x to be the ratio of the two telescoping sums x = (sum over k=1..{n_terms} of [cos(B_k) - cos(A_k)]) divided by (sum over k=1..{n_terms} of [sin(B_k) - sin(A_k)]). All angles are in degrees. What is the greatest integer that does not exceed {scale}·x?'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # We construct parameters so that the derived closed-form x = tan(beta) is valid and well-conditioned.
    # beta = ((2*b + N + 1 + r) * d)/2 degrees, with d = step_deg, N = n_terms, r = shift, b = base_offset.
    # Constraints we enforce:
    # 1) r*d not multiple of 360 (to avoid e^{ir theta} - 1 = 0 and S = 0)
    # 2) N*d not multiple of 360 (to avoid the base sum S1 = 0 and S = 0)
    # 3) beta mod 180 not near 90 degrees (to avoid tan singularity)
    # 4) beta mod 180 not near "nice" special angles to avoid trivial exact values
    # 5) scaled answer not too close to an integer to avoid rounding ambiguities
    attempts = 0
    while attempts < 2000:
        attempts += 1
        step_deg = rng.randint(1, 12)
        n_terms = rng.randint(20, 140)
        shift = rng.randint(2, 30)
        base_offset = rng.randint(0, 80)
        scale = rng.choice([100, 125, 150, 175, 200, 225, 250, 300, 325, 350, 375, 400])

        # Constraint checks
        # Avoid zero differences
        if (shift * step_deg) % 360 == 0:
            continue
        if (n_terms * step_deg) % 360 == 0:
            continue

        beta_deg = (2 * base_offset + n_terms + 1 + shift) * step_deg / 2.0
        # normalize to [0, 180) for distance checks
        beta_mod = beta_deg % 180.0

        # Avoid being too close to 90 degrees (tan blow-up)
        if abs(beta_mod - 90.0) < 4.0:
            continue

        # Avoid common special angles (multiples of 15 degrees) for difficulty
        is_near_special = False
        for k in range(13):  # 0, 15, 30, ..., 180
            if abs(beta_mod - 15.0 * k) < 0.6:
                is_near_special = True
                break
        if is_near_special:
            continue

        # Compute x = tan(beta)
        beta_rad = math.radians(beta_deg)
        # Guard against accidental singularities due to floating error
        c = math.cos(beta_rad)
        if abs(c) < 1e-10:
            continue
        x = math.tan(beta_rad)

        # Keep magnitude moderate for stability and nontriviality
        if not math.isfinite(x):
            continue
        if abs(x) < 0.2 or abs(x) > 6.0:
            continue

        scaled = scale * x
        if not math.isfinite(scaled):
            continue
        if abs(scaled) > 1e6:
            continue

        # Avoid near-integer scaled results
        if abs(scaled - round(scaled)) < 1e-6:
            continue

        return {
            'step_deg': int(step_deg),
            'base_offset': int(base_offset),
            'n_terms': int(n_terms),
            'shift': int(shift),
            'scale': int(scale)
        }

    # Fallback deterministic valid instance if random attempts fail (extremely unlikely)
    step_deg = 3
    base_offset = 7
    n_terms = 44
    shift = 5
    scale = 250
    return {
        'step_deg': step_deg,
        'base_offset': base_offset,
        'n_terms': n_terms,
        'shift': shift,
        'scale': scale
    }

        import math

def verifier(assign):
    # Validate presence and basic types
    required = ['step_deg', 'base_offset', 'n_terms', 'shift', 'scale']
    for k in required:
        if k not in assign:
            # Missing parameter
            return (False, None)  # missing key
    try:
        step_deg = int(assign['step_deg'])
        base_offset = int(assign['base_offset'])
        n_terms = int(assign['n_terms'])
        shift = int(assign['shift'])
        scale = int(assign['scale'])
    except Exception:
        return (False, None)  # non-integer inputs

    # Domain checks
    if step_deg <= 0 or step_deg >= 360:
        return (False, None)  # invalid step
    if n_terms < 2:
        return (False, None)  # too few terms
    if shift < 1:
        return (False, None)  # invalid shift
    if base_offset < 0:
        return (False, None)  # invalid base offset
    if scale <= 0:
        return (False, None)  # invalid scale

    # Structural non-degeneracy
    if (shift * step_deg) % 360 == 0:
        return (False, None)  # e^{i r theta} - 1 = 0 leads to 0/0
    if (n_terms * step_deg) % 360 == 0:
        return (False, None)  # base sum vanishes, 0/0

    # Closed-form reduction: x = tan(beta), where
    # beta = ((2*b + N + 1 + r) * step_deg)/2 degrees.
    beta_deg = (2 * base_offset + n_terms + 1 + shift) * step_deg / 2.0
    beta_rad = math.radians(beta_deg)

    # Guard against tan singularity
    if abs(math.cos(beta_rad)) < 1e-12:
        return (False, None)

    x = math.tan(beta_rad)
    if not math.isfinite(x):
        return (False, None)

    scaled = scale * x
    if not math.isfinite(scaled):
        return (False, None)

    # Ensure not too close to an integer boundary to avoid ambiguity
    if abs(scaled - round(scaled)) < 1e-7:
        return (False, None)

    ans = math.floor(scaled)

    # Additional correctness cross-check (optional): compute from the literal sums to ensure integrity
    # This is a higher-cost verification but with small N it's fine; we run with radians directly.
    theta = math.radians(step_deg)
    # Check non-degeneracy: if denominator equals 0 numerically, reject
    num = 0.0
    den = 0.0
    for k in range(1, n_terms + 1):
        Ak = (base_offset + k) * theta
        Bk = (base_offset + k + shift) * theta
        num += math.cos(Bk) - math.cos(Ak)
        den += math.sin(Bk) - math.sin(Ak)
    if abs(den) < 1e-10:
        return (False, None)
    x_literal = num / den
    if not math.isfinite(x_literal):
        return (False, None)
    # Consistency check between closed-form and literal evaluation
    if abs(x_literal - x) > 1e-7 * max(1.0, abs(x)):
        return (False, None)

    return True, int(ans)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

